select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146057 and t.language='nl')='{"text":"Terwijl Ever haar nieuwe vermogens als onsterfelijke leert kennen, wordt Damen getroffen door een mysterieuze verzwakking. Zijn herinneringen en identiteit lijken mee te verdwijnen. Op zoek naar een oplossing reist Ever naar Summerland, waar zij meer ontdekt over zijn verleden en over de mogelijkheden om de tijd te beïnvloeden. Een naderend uitzonderlijk moment stelt haar voor een keuze. Zij kan proberen het ongeluk van haar familie ongedaan te maken, of in het heden blijven om Damen te helpen.","work_id":987146057,"evidence":[{"note":"Retain existing Work5877 Blue Moon / Alyson Noël and exact Dutch Blauwe Maan 9789045801896 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-026.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p325831939"],"reference":"work:5877","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-026.json","sources":["https://openlibrary.org/works/OL15638721W","https://data.bibliotheken.nl/id/nbt/p325831939"]},{"note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789045801896","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":7322422,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-