erzoekstalenten bieden niet meteen de gebruikelijke houvast.","work_id":987146023,"evidence":[{"note":"Retain existing Work3386 All In / Jennifer Lynn Barnes and exact Dutch All In 9789463496605 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-026.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p457405457"],"reference":"work:3386","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-026.json","sources":["https://openlibrary.org/works/OL20011828W","https://data.bibliotheken.nl/id/nbt/p457405457"]},{"note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789463496605","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15241295,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:26:38.922Z","editionKey":"/books/OL62370431M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL20011828W","reviewed_at":"2026-11-03T09:26:38.922+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-047","review_status":"approved","bound_author_id":924300308}'::jsonb as